import { createDocumentHandler } from "@/lib/artifacts/server";
import { decodeNotebookRef, encodeNotebookRef } from "@/lib/notebook/ref";

/**
 * Notebooks are never generated by the model.
 *
 * A notebook is a list of sources, and every source is a file the user supplied
 * or a page they pointed at. So there is nothing for the model to stream: the
 * streaming callbacks hand the client the *reference*, and the studio resolves
 * the sources itself.
 */
export const notebookDocumentHandler = createDocumentHandler<"notebook">({
  kind: "notebook",
  onCreateDocument: ({ dataStream, title }) => {
    const ref = decodeNotebookRef(null);

    dataStream.write({
      data: encodeNotebookRef({ sources: [], title }),
      transient: true,
      type: "data-notebookDelta",
    });

    return Promise.resolve(
      encodeNotebookRef({ sources: [], title: ref?.title ?? title })
    );
  },
  onUpdateDocument: ({ document, dataStream }) => {
    const content = document.content ?? encodeNotebookRef({ sources: [] });

    dataStream.write({
      data: content,
      transient: true,
      type: "data-notebookDelta",
    });

    return Promise.resolve(content);
  },
});
